"ctx": "Een speedpedelec is een variant van de elektrische fiets die tot 45 kilometer per uur kan rijden. Bestuurders van speedpedelecs zijn verplicht om een helm te dragen.",
"q": "Is een helm een substitutiegoed of een complementair goed van de\n speedpedelec? Geef een argument voor je keuze.",
"model": "Een voorbeeld van een juist antwoord is: Een helm is een complementair goed, omdat de helm en de speedpedelec tegelijkertijd worden gebruikt / omdat de helm verplicht is bij gebruik van de speedpedelec.",
"pnt": 1
