"ctx": "Het huidige pensioenstelsel bestaat uit bedrijfspensioenen, die via het kapitaaldekkingsstelsel gefinancierd worden, en uit AOW-uitkeringen, die via het omslagstelsel gefinancierd worden. In periodes van lage rente verslechtert de betaalbaarheid van het kapitaaldekkingsstelsel.",
"q": "Leg uit dat een lage rente de betaalbaarheid van het\n kapitaaldekkingsstelsel onder druk zet.",
"model": "Voorbeelden van een juist antwoord zijn:\n• Bij een lage rente groeit het gespaarde pensioenbedrag minder snel dan bij een hoge rente (bij gelijkblijvende pensioenpremie), en (1p)\n• dan is het beschikbare kapitaal (uit sparen en beleggen) niet voldoende om de hoogte van de pensioenen te kunnen garanderen / om de toekomstige pensioenen te kunnen betalen. (1p)",
