"ctx": "Aan de andere kant verwacht het CPB dat het aanbod van arbeid binnen de groep van 20- tot 66-jarigen zal toenemen, doordat een groter deel van die groep besluit te gaan werken.",
"q": "Leg uit dat deze ontwikkeling zowel kan leiden tot hogere toekomstige overheidsinkomsten alsook tot lagere toekomstige overheidsuitgaven.",
