"ctx": "De recente verhoging van de pensioenleeftijd lost het houdbaarheidstekort gedeeltelijk op. Om de betaalbaarheid van overheidsvoorzieningen verder te verbeteren, stelt een econoom een aantal beleidsopties voor aan de Nederlandse regering: 1 Verhoog het tarief van alle belastingschijven in het progressieve belastingstelsel met 1 procentpunt. 2 Verlaag de uitkeringen, inclusief de AOW. Een van de twee beleidsopties kan leiden tot een daling van het arbeidsaanbod.",
"q": "Leg uit welke van de twee beleidsopties kan leiden tot een daling van het\n arbeidsaanbod.",
