"nr": 22,
"ctx": "De AOW is een basispensioen voor ouderen. Door de vergrijzing verslechtert de betaalbaarheid van de AOW: er zijn minder werkenden die premie betalen waarmee de uitkeringen in dat jaar worden betaald. De Nederlandse overheid heeft daarom een aantal jaar geleden besloten de AOW-leeftijd geleidelijk te verhogen van 65 naar 67 jaar en daarna te koppelen aan de levensverwachting. De AOW-leeftijd stijgt dan mee met de gemiddelde levensverwachting.",
"q": "Leg uit dat het verhogen van de AOW-leeftijd de betaalbaarheid van de AOW verbetert. Maak in je antwoord gebruik van zowel de inkomsten als de uitgaven van de overheid.",
"model": "Een voorbeeld van een juist antwoord is:\n• De inkomsten van de overheid nemen toe, omdat werkenden later met pensioen gaan, waardoor er meer premie wordt betaald. (1p)\n• De uitgaven van de overheid nemen af, omdat de duur van de pensioentijd / het aantal AOW-uitkeringen afneemt. (Hierdoor verbetert de betaalbaarheid). (1p)",
