"ctx": "De overheid in dit land heeft een vereveningsfonds ingesteld. Alle zorgverzekeraars storten per verzekerde een bedrag in dit fonds. Zorgverzekeraars met relatief veel slechte risico’s kunnen een beroep doen op dit fonds en kunnen zo een deel van de zorgkosten die ze maken compenseren.",
"q": "Leg uit dat een doelgroepencampagne minder financieel voordeel voor de\n zorgverzekeraar oplevert als er sprake is van een vereveningsfonds.",
"model": "Een voorbeeld van een juiste uitleg is:\n• Door doelgroepencampagne probeert de verzekeraar vooral goede risico’s, zoals studenten aan te trekken. (1p)\n• Door relatief meer goede risico’s valt een deel van de vergoeding vanuit het vereveningsfonds weg, waardoor doelgroepencampagne financieel minder voordeel oplevert. (1p)",
