"ctx": "De populariteit van fatbikes zorgt voor een forse toename van het aantal verkeersongevallen onder jongeren. Deze ongevallen leiden tot kosten voor politie en justitie.",
"q": "Leg uit dat het gebruik van fatbikes leidt tot negatieve externe effecten,\n met als gevolg maatschappelijke kosten.",
"model": "Een juist antwoord bevat in relatie tot de context:\n• Een voorbeeld van een negatief extern effect waarbij wordt benoemd dat deze kosten niet zijn verwerkt in de prijs van de fatbike. (1p)\n• Een uitleg dat hierdoor sprake is van maatschappelijke kosten. (1p)\nEen voorbeeld van een juist antwoord is:\n• De kosten voor politie en justitie zijn kosten die niet in de prijs van een fatbike zijn verwerkt (negatief extern effect). (1p)\n• Deze kosten komen ten laste van anderen dan de fatbikegebruiker (en komen dus ten laste van de maatschappij). (1p)",
