"model": "(1) marktfalen (2) hoger\nIndien twee antwoorden juist 1 Indien minder dan twee antwoorden juist (0p)\n5 Aanleveren scores\nVerwerk de scores van de alfabetisch eerste vijf kandidaten per examinator in de applicatie Wolf. Cito gebruikt deze gegevens voor de analyse van de examens. Om de gegevens voor dit doel met Cito uit te wisselen dient u ze uiterlijk op 22 mei te accorderen.\nOok na 22 mei kunt u nog tot en met 10 juni gegevens voor Cito accorderen. Deze gegevens worden niet meer meegenomen in de hierboven genoemde analyses, maar worden wel meegenomen bij het genereren van de groepsrapportage.\nNa accordering voor Cito kunt u in Wolf de gegevens nog wijzigen om ze vervolgens vrij te geven voor het overleg met de externe corrector. Deze optie is relevant als u Wolf ook gebruikt voor uitwisseling van de gegevens met de externe corrector.\nTweede tijdvak Ook in het tweede tijdvak wordt de normering mede gebaseerd op door kandidaten behaalde scores. Wissel te zijner tijd ook voor al uw tweede-tijdvak-kandidaten de scores uit met Cito via Wolf. Dit geldt niet voor de aangewezen vakken.\n6 Bronvermeldingen\nOverige tabellen, grafieken en teksten bron Stichting Cito Instituut voor Toetsontwikkeling, 2026",
"pnt": 1
